# Part-4 plates + inserts prompts. Run: python stil/canli/prompts/make_p4_pl.py
import os

HERE = os.path.dirname(os.path.abspath(__file__))
HEAD = "Use your built-in image_gen tool to generate exactly ONE image, 16:9 landscape. Do not copy or move any files and do not run shell commands; just generate it, then print DONE.\n\n"
STYLE = "Match the attached style references EXACTLY: flat silk-screen print, navy #18203A shapes with thin cream #F3EFE4 trim lines, moon-yellow #F0D35A accents, fine grain, slight misregistration, rough dry-ink edges. Palette ONLY navy, cream, moon yellow: no other hue, no gradients, no soft shading, no 3D render look, no photorealism. ABSOLUTELY NO text, letters, numbers, logos or watermarks anywhere. Fully opaque full-frame picture, NO magenta, NO transparent areas.\n"
HUMAN = "The human is FACELESS: a flat navy silhouette with a thin cream rim line, bare feet and hands drawn simply, yellow sticky notes (small square pads with a tiny tape tab) stuck on the clothes, exactly like the canonical character reference. Same drawing language as the reference. "

P = {}
P['p4-pl-bus-door'] = (HEAD + STYLE +
    "Attached: (1) the interior of this film's night bus, (2) a style frame of the bus doorway. Draw the inside of the SAME night bus, the camera facing the bus's SIDE DOORWAY STRAIGHT ON, perfectly frontal and symmetric, the doorway centred and filling about 45% of the width and 85% of the height. The doorway is an EMPTY open rectangle with straight vertical sides and a straight horizontal top: NO door leaves, NO door panels, NO glass, NO handles drawn at all (they are added later in code); just the bare cream-rimmed navy door frame, with a lit step (a yellow-lined step edge) at its bottom and a horizontal bus floor line either side of the step. Left and right of the doorway: the navy bus interior wall with cream rim lines, a grab pole at each side, rows of navy seat backs at the far left and far right edges, moon-yellow ceiling light strips along the top. "
    "THROUGH the doorway the night street: navy buildings with moon-yellow lit windows, one cast-iron street lamp with a yellow glow, a wet pavement with yellow reflections and cream streaks, a big round moon-yellow moon in the sky. NO people, NO figures, no sticky notes." )
P['p4-pl-ins-foot'] = (HEAD + STYLE + HUMAN +
    "Attached: (1) canonical character reference, (2) his half-body walking drawing, (3) a night-run style frame. Draw a CLOSE-UP at ground level, strict SIDE VIEW from the side: his BARE navy foot (cream rim) slamming down into a shallow puddle on a wet night street, the foot facing right, toes slightly down. His navy trouser cuff and the bottom of his shin enter from the TOP edge of the frame. A crown-shaped SPLASH of cream and moon-yellow droplets bursts up around the foot. The puddle is a wide flat ellipse across the lower half; it reflects a round moon-yellow moon and lit yellow windows as broken yellow shapes. Behind: a dim navy wet pavement with cream streaks and a blurred strip of dark buildings with yellow windows. No other person." )
P['p4-pl-ins-fist'] = (HEAD + STYLE + HUMAN +
    "Attached: (1) canonical character reference, (2) his half-body walking drawing. Draw a CLOSE-UP of his navy FIST (thin cream rim), clenched in a running swing, held out to the right: the fist is clenched around ONE moon-yellow sticky note held at its EDGE: the note sticks out between thumb and index finger, pinched, the note large and clearly readable as a square pad with a tape tab, blank. His FOREARM enters from the LEFT edge of the frame, in a navy sleeve with ANOTHER yellow sticky note stuck on the sleeve, the arm swinging forward and slightly up. Behind: the night street as halftone moon-yellow bokeh dots of different sizes on a flat navy field (no buildings drawn, just dots), a few cream speed streaks. No face, no other body part." )
P['p4-pl-ins-face'] = (HEAD + STYLE + HUMAN +
    "Attached: (1) canonical character reference, (2) his over-the-shoulder back drawing for the hair. Draw a CLOSE PROFILE of his head and shoulders facing RIGHT, filling most of the frame (head about half the frame height), as a faceless navy silhouette with a thin cream rim line, HIS MESSY HAIR exactly as in the canonical reference, a yellow sticky note on the shoulder. He is PANTING: the head tilted slightly up, the chin raised, and the MOUTH area is a SMALL OPEN GAP (a small notch) in the profile line. Do NOT draw breath puffs, steam, sweat drops or any marks around the mouth. No facial features other than that gap. Behind: night street bokeh, moon-yellow halftone dots of different sizes on flat navy, no buildings." )
for k, v in P.items():
    open(os.path.join(HERE, k + '.txt'), 'w', encoding='utf8').write(v)
print(len(P), 'prompts')
